describe('Mobile Hamburger Menu', () => {
    beforeEach(() => {
        cy.visit('/'); // Replace with the actual URL of the application
    });

    it('should open the hamburger menu when clicked', () => {
        cy.get('.hamburger-menu').click(); // Adjust selector as needed
        cy.get('.menu').should('be.visible'); // Adjust selector as needed
    });

    it('should close the hamburger menu when clicked again', () => {
        cy.get('.hamburger-menu').click(); // Open the menu
        cy.get('.hamburger-menu').click(); // Close the menu
        cy.get('.menu').should('not.be.visible'); // Adjust selector as needed
    });
});
